code.source:
#include <iostream>
#include <memory>
using namespace std;

int main() {
    shared_ptr<int> a = make_shared<int>(5);
    cout << a.use_count() << endl;
    {
        shared_ptr<int> b = a;
        cout << a.use_count() << endl;
    }
    cout << a.use_count() << endl;
    return 0;
}

#include <iostream>
#include <memory>
using namespace std;

int main() {
    weak_ptr<int> w;
    {
        shared_ptr<int> s = make_shared<int>(7);
        w = s;
        cout << w.expired() << endl;
        if (auto locked = w.lock()) {
            cout << *locked << endl;
        }
    }
    cout << w.expired() << endl;
    return 0;
}

